def minimum_spanning_tree(weight_by_edge):
    group_by_node = {}  # Define the group_by_node dictionary here
    mst_edges = set()

    for edge in sorted(weight_by_edge, key=weight_by_edge.__getitem__):
        u, v = edge
        if group_by_node.setdefault(u, {u}) != group_by_node.setdefault(v, {v}):
            mst_edges.add(edge)
            # Find the root of each component and merge them
            root_u = find_root(group_by_node[u])
            root_v = find_root(group_by_node[v])
            for node in group_by_node[root_v]:
                group_by_node[node] = root_u

    return mst_edges

def find_root(node):
    if node not in group_by_node:
        group_by_node[node] = node
    elif node != group_by_node[node]:
        group_by_node[node] = find_root(group_by_node[node])
    return group_by_node[node]

# Example usage
weight_by_edge = {
    (1, 2): 10,
    (2, 3): 15,
    (3, 4): 10,
    (1, 4): 10
}

result = minimum_spanning_tree(weight_by_edge)
assert result == {(1, 2), (3, 4), (1, 4)}

from collections import defaultdict

def shortest_path_lengths(n, length_by_edge):
    length_by_path = defaultdict(lambda: float('inf'))
    length_by_path.update({(i, i): 0 for i in range(n)})
    length_by_path.update(length_by_edge)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                length_by_path[i, j] = min(
                    length_by_path[i, j],
                    length_by_path[i, k] + length_by_path[j, k]
                )

    return length_by_path

