def quicksort(arr):
    if not arr:
        return []

    pivot = arr[0]
    lesser = []
    greater = []

    for x in arr[1:]:
        if x < pivot:
            lesser.append(x)
        elif x > pivot:
            greater.append(x)

    return quicksort(lesser) + [pivot] + quicksort(greater)

