class Node:
    def __init__(self, value):
        self.value = value
        self.incoming_nodes = set()
        self.outgoing_nodes = set()

def topological_ordering(nodes):
    # Create a dictionary to keep track of nodes and their in-degree
    in_degree = {node: 0 for node in nodes}

    # Count the number of incoming edges for each node
    for node in nodes:
        for next_node in node.outgoing_nodes:
            in_degree[next_node] += 1

    # Initialize a queue with nodes that have no incoming edges
    queue = [node for node in nodes if in_degree[node] == 0]

    ordered_nodes = []

    while queue:
        current_node = queue.pop(0)
        ordered_nodes.append(current_node.value)  # Convert Node to its value before appending

        # Decrease the in-degree of each outgoing node
        for next_node in current_node.outgoing_nodes:
            in_degree[next_node] -= 1

            # If a node's in-degree becomes zero, add it to the queue
            if in_degree[next_node] == 0:
                queue.append(next_node)

    return ordered_nodes

