def rpn_eval(tokens):

    def op(symbol, a, b):
        if symbol == '/':
            if b == 0:
                raise ValueError('Division by zero')
            return a / b
        else:
            return {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b}[symbol](a, b)
    stack = []
    for token in tokens:
        if isinstance(token, float):
            stack.append(token)
        else:
            a = stack.pop()
            b = stack.pop()
            result = op(token, a, b)
            stack.append(result)
    assert len(stack) == 1, 'The result of the RPN expression should be a single value'
    return stack[0]



